def day_span(rows, key, iso, start, split, mins):
	latest = -1
	for raw in rows:
		parts = split(raw, 7)
		if parts[0].lower() not in [key.lower(), iso.lower()]:
			continue
		finish = mins(parts[2])
		if finish > latest:
			latest = finish
	if latest <= start * 60:
		return start * 60 + 60
	return ((latest + 59) // 60) * 60

