			kind = cols[6].lower()
			if kind not in ["talk", "workshop", "social", "break"]:
				kind = "talk"
			speaker = cols[5]
			sessions.append({
				"id": anchor(key, cols[1], "" if whole else place, slugify),
				"from": clock(begin),
				"to": clock(finish),
				"from_iso": iso + "T" + clock(begin),
				"to_iso": iso + "T" + clock(finish),
				"title": cols[4],
				"speaker": speaker,
				"has_speaker": len(speaker) > 0,
				"room": (", " + where) if speaker else where,
				"a": str((begin - window) // 5 + 1),
				"b": str((min(finish, end) - window) // 5 + 1),
				"c": col,
				"d": str(finish - begin),
				"kind": kind,
				"order": begin * 10 + order,
			})
		sessions = sorted(sessions, key=lambda s: s["order"])
		named = weekday(iso)
		slug = slugify(key)[:3]
		first = len(days) == 0
		days.append({
			"id": slug,
			"tab_id": "tab-" + slug,
			"name": named["name"] or key,
			"sub": (named["date"] + ", " if named["date"] else "") + clock(window) + " to " + clock(end),
			"heading": (named["name"] + " " + named["date"]).strip() or key,
			"iso": iso,
			"start": clock(window),
			"rows": str(count),
			"cols": str(max(1, len(rooms))),
			"active": "true" if first else "false",
			"tabindex": "0" if first else "-1",
			"rooms": rooms,
			"hours": hours,
			"sessions": sessions,
		})
except:
	days = []
component.days = days
